// ===== B09 · Modelo físico (se ejecuta cada 1 s real) =====
// Integra 'factor_tiempo' pasos de 1 s simulado (Euler explícito).
// Ecuaciones:
//   dV/dt     = (Qin - Qout)/60                                  [L/s]
//   dD/dt     = (Dsp - D)/TAU_DOSE                               retardo de dosificación
//   dTurb/dt  = (Qin/60)/V·(Turb_in - Turb) - k(D)·Turb,  k(D)=KMAX·D/(D+KD)
//   dpH/dt    = (pH_in - ALPHA·D - pH)/TAU_PH
const S = global.get('b09');
if (!S) return null;
const c = S.cfg, p = S.proc, a = S.act, k = S.kpi;

function gauss() { let u = 0, v = 0; while (!u) u = Math.random(); while (!v) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); }

const steps = Math.max(1, Math.round(S.sp.factor_tiempo));
for (let i = 0; i < steps; i++) {
    const dt = 1;
    // Perturbación justificada: variabilidad lenta de la turbidez del agua cruda (paseo aleatorio acotado)
    p.turb_in += 0.002 * (p.turb_in_base - p.turb_in) * dt + 0.05 * gauss();
    if (p.turb_in < 0.5) p.turb_in = 0.5;

    // Caudales dependen de las bombas (ruido ±2 % en la bomba de alimentación)
    const bombaOK = a.bomba_on && !a.bomba_falla;
    p.Qin = bombaOK ? c.QIN_NOM * (1 + 0.02 * gauss()) : 0;
    if (a.descarga_on && p.V <= 1) a.descarga_on = false;
    p.Qout = a.descarga_on ? c.QOUT_NOM : 0;

    // Dosificación con retardo de primer orden (no se dosifica con tanque vacío)
    const doseCmd = p.V > 50 ? S.sp.dosificacion_Lh : 0;
    p.dose_eff += (doseCmd - p.dose_eff) * dt / c.TAU_DOSE;

    // Balance de volumen con rebose
    p.V += (p.Qin - p.Qout) / 60 * dt;
    p.overflow = false;
    if (p.V > c.CAP) { k.rebose_L += p.V - c.CAP; p.V = c.CAP; p.overflow = true; }
    if (p.V < 0) p.V = 0;

    // Calidad: mezcla completa + remoción por coagulación
    const dil = (p.Qin / 60) / Math.max(p.V, 50);
    const kr = c.KMAX * p.dose_eff / (p.dose_eff + c.KD);
    p.turb += (dil * (p.turb_in - p.turb) - kr * p.turb) * dt;
    if (p.turb < 0) p.turb = 0;
    const pHeq = p.pH_in - c.ALPHA * p.dose_eff;
    p.pH += (pHeq - p.pH) / c.TAU_PH * dt;
    p.pH = Math.min(14, Math.max(0, p.pH));

    // Acumuladores de KPI
    p.en_spec = p.pH >= c.PH_MIN && p.pH <= c.PH_MAX && p.turb < c.TURB_OBJ;
    k.t_total += dt;
    if (p.en_spec) k.t_spec += dt;
    if (!a.bomba_falla) k.t_disp += dt;
    k.reactivo_L += doseCmd / 3600 * dt;
    k.descargado_L += p.Qout / 60 * dt;
    if (p.en_spec) k.tratado_L += p.Qout / 60 * dt;
    p.t_sim += dt;
}

// Medición con ruido de instrumento (el ruido no altera el estado del modelo)
S.meas = {
