    log('EVENTO', 'INT_NIVEL', 'P-101 detenida por enclavamiento de nivel alto');
}
if (a.descarga_on && p.V <= 1) {
    a.descarga_on = false; log('EVENTO', 'INT_VACIO', 'Descarga detenida: tanque vacío');
}
if (sp.modo === 'auto' && a.descarga_on && !p.en_spec) {
    a.descarga_on = false; log('EVENTO', 'INT_CALIDAD', 'Descarga detenida: agua fuera de especificación');
}

// ---- 2. Alarmas (con histéresis para evitar intermitencia) ----
const prev = id => !!(S.alarms[id] && S.alarms[id].activa);
