    { id: 'ALM_PH', nombre: 'pH fuera de rango', condicion: `pH < ${c.PH_MIN} o pH > ${c.PH_MAX}`, unidad: 'pH', valor: p.pH,
      on: prev('ALM_PH') ? (p.pH < c.PH_MIN + 0.05 || p.pH > c.PH_MAX - 0.05) : (p.pH < c.PH_MIN || p.pH > c.PH_MAX),
      sev: (p.pH < 6.0 || p.pH > 9.0) ? 'CRITICA' : 'ALTA' },
