      on: prev('ALM_TURB') ? p.turb > c.TURB_OBJ * 0.9 : p.turb > c.TURB_OBJ,
      sev: p.turb > 20 ? 'ALTA' : 'MEDIA' },
    { id: 'ALM_OVF', nombre: 'Tanque desbordado', condicion: `nivel ≥ ${0.99 * c.CAP} L (rebose)`, unidad: 'L', valor: p.V,
      on: prev('ALM_OVF') ? p.V > 0.97 * c.CAP : p.V >= 0.99 * c.CAP, sev: 'CRITICA' },
    { id: 'ALM_BOMBA', nombre: 'Falla bomba P-101', condicion: 'señal de falla activa', unidad: '', valor: a.bomba_falla ? 1 : 0,
