// ---- 3. Histórico (1 muestra por segundo real) ----
const m = S.meas, r = (v, n) => Math.round(v * 10 ** n) / 10 ** n;
S.history.push({ ts: m.ts, t: Math.round(p.t_sim), nivel: r(m.V, 1), caudal_entrada: r(m.Qin, 1),
    caudal_salida: r(m.Qout, 1), ph: r(m.pH, 3), turbidez: r(m.turb, 2), dosificacion: r(sp.dosificacion_Lh, 2) });
while (S.history.length > c.HIST_MAX) S.history.shift();

const nAct = Object.values(S.alarms).filter(x => x.activa).length;
node.status({ fill: nAct ? 'red' : 'green', shape: 'ring', text: `${nAct} alarma(s) activa(s)` });
return null;

// ===== Responder: cabeceras, latencia simulada y registro de solicitudes de control =====
const S0 = global.get('b09');
const lat = (S0 && S0.sp && S0.sp.latencia_ms) || 0;
// Cabeceras de la respuesta (JSON, sin caché, CORS)
msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store',
                'Access-Control-Allow-Origin': '*', 'X-Device': 'B09' };
function finish() {
    const S = global.get('b09');
    if (msg._logCmd && S) {
        const entry = { ts: new Date().toISOString(), metodo: msg.req.method, ruta: msg.req.originalUrl || msg.req.url,
                        comando: msg._cmd || null, codigo: msg.statusCode, tiempo_ms: Date.now() - msg._t0 };
        S.cmd_log.push(entry);
        if (S.cmd_log.length > 300) S.cmd_log.shift();
        if (msg.payload && typeof msg.payload === 'object') msg.payload.tiempo_servidor_ms = entry.tiempo_ms;
        node.status({ fill: msg.statusCode < 300 ? 'green' : 'red', shape: 'dot', text: `${entry.metodo} ${entry.comando} → ${entry.codigo} (${entry.tiempo_ms} ms)` });
    }
    node.send(msg);
}
if (lat > 0) setTimeout(finish, lat); else finish();
return null;

// GET /api/B09/telemetry → lectura instantánea de las variables del proceso
const S = global.get('b09');
if (!S || !S.meas) { msg.statusCode = 503; msg.payload = { device: 'B09', ts: new Date().toISOString(), error: 'Simulador no inicializado' }; return msg; }
const m = S.meas, r = (v, n) => Math.round(v * 10 ** n) / 10 ** n;
msg.statusCode = 200;
msg.payload = {
    device: 'B09', ts: m.ts, t_sim_s: Math.round(S.proc.t_sim),
    data: {
        nivel:          { value: r(m.V, 1), unit: 'L' },
        nivel_pct:      { value: r(100 * m.V / S.cfg.CAP, 1), unit: '%' },
        caudal_entrada: { value: r(m.Qin, 1), unit: 'L/min' },
        caudal_salida:  { value: r(m.Qout, 1), unit: 'L/min' },
        caudal_neto:    { value: r(m.Qin - m.Qout, 1), unit: 'L/min' },
        ph:             { value: r(m.pH, 2), unit: 'pH' },
        turbidez:       { value: r(m.turb, 2), unit: 'NTU' },
        dosificacion:   { value: r(m.dose, 2), unit: 'L/h' },
        dosis_efectiva: { value: r(m.dose_eff, 2), unit: 'L/h' }
    }
};
return msg;

// GET /api/B09/status → estado de actuadores, modo, consignas y resumen de alarmas
const S = global.get('b09');
if (!S) { msg.statusCode = 503; msg.payload = { device: 'B09', ts: new Date().toISOString(), error: 'Simulador no inicializado' }; return msg; }
const a = S.act, p = S.proc, c = S.cfg;
const al = Object.values(S.alarms);
msg.statusCode = 200;
msg.payload = {
    device: 'B09', ts: new Date().toISOString(), t_sim_s: Math.round(p.t_sim),
    modo: S.sp.modo,
    en_especificacion: p.en_spec,
    rebosando: p.overflow,
    bomba_alimentacion: { id: 'P-101', estado: a.bomba_falla ? 'FALLA' : (a.bomba_on ? 'ON' : 'OFF'),
                          comandada: a.bomba_on, falla: a.bomba_falla, motivo: a.motivo_bomba },
    bomba_descarga: { id: 'P-103', estado: a.descarga_on ? 'ON' : 'OFF' },
    dosificadora: { id: 'P-102', estado: S.sp.dosificacion_Lh > 0 && p.V > 50 ? 'ON' : 'OFF',
                    consigna_Lh: S.sp.dosificacion_Lh, efectiva_Lh: Math.round(p.dose_eff * 100) / 100 },
    agitador: { id: 'M-101', estado: p.V > 50 ? 'ON' : 'OFF' },
    setpoints: Object.assign({}, S.sp),
    perturbacion: { turbidez_entrada_NTU: Math.round(p.turb_in * 10) / 10, ph_entrada: p.pH_in },
    alarmas: { activas: al.filter(x => x.activa).length, sin_reconocer: al.filter(x => !x.reconocida).length },
    limites: { capacidad_L: c.CAP, ph_min: c.PH_MIN, ph_max: c.PH_MAX, turbidez_objetivo_NTU: c.TURB_OBJ,
               dosificacion_max_Lh: c.DOSE_MAX, volumen_min_descarga_L: c.V_MIN_DESC }
};
return msg;

// GET /api/B09/kpis → cinco KPI con fórmula y unidades
const S = global.get('b09');
if (!S) { msg.statusCode = 503; msg.payload = { device: 'B09', ts: new Date().toISOString(), error: 'Simulador no inicializado' }; return msg; }
const k = S.kpi, T = Math.max(k.t_total, 1), r = (v, n) => Math.round(v * 10 ** n) / 10 ** n;
msg.statusCode = 200;
msg.payload = {
    device: 'B09', ts: new Date().toISOString(), t_sim_s: Math.round(S.proc.t_sim),
    kpis: {
        volumen_tratado:    { value: r(k.tratado_L / 1000, 3), unit: 'm³',
            formula: 'Σ Qsal·Δt (solo si pH∈[6,5;8,5] y turbidez<5 NTU) / 1000' },
        tiempo_en_especificacion: { value: r(100 * k.t_spec / T, 1), unit: '%',
            formula: '100 · t(en especificación) / t(proceso)' },
        consumo_reactivo:   { value: r(k.reactivo_L, 3), unit: 'L',
            formula: 'Σ Dosificación[L/h]·Δt/3600' },
        tiempo_proceso:     { value: r(k.t_total / 60, 1), unit: 'min',
            formula: 'Σ Δt simulado / 60' },
        disponibilidad:     { value: r(100 * k.t_disp / T, 1), unit: '%',
            formula: '100 · t(P-101 sin falla) / t(proceso)' }
    },
    adicionales: {
        volumen_descargado: { value: r(k.descargado_L / 1000, 3), unit: 'm³' },
        volumen_rebosado:   { value: r(k.rebose_L, 1), unit: 'L' }
    }
};
return msg;

// GET /api/B09/history?window=10&vars=nivel,turbidez&max_points=300
const S = global.get('b09');
const q = (msg.req && msg.req.query) || {};
const VARS = { nivel: 'L', caudal_entrada: 'L/min', caudal_salida: 'L/min', ph: 'pH', turbidez: 'NTU', dosificacion: 'L/h' };
function bad(err) { msg.statusCode = 400; msg.payload = { device: 'B09', ts: new Date().toISOString(), error: err,
    parametros: { window: 'minutos reales, 1–60 (defecto 10)', vars: Object.keys(VARS).join(','), max_points: '10–1000 (defecto 300)' } }; return msg; }
if (!S) { msg.statusCode = 503; msg.payload = { error: 'Simulador no inicializado' }; return msg; }
const win = q.window === undefined ? 10 : Number(q.window);
if (!Number.isFinite(win) || win < 1 || win > 60) return bad('window fuera de rango (1–60 min)');
const maxp = q.max_points === undefined ? 300 : Number(q.max_points);
if (!Number.isInteger(maxp) || maxp < 10 || maxp > 1000) return bad('max_points fuera de rango (10–1000)');
const vars = q.vars ? String(q.vars).split(',').map(s => s.trim()).filter(Boolean) : Object.keys(VARS);
const unk = vars.filter(v => !VARS[v]);
if (unk.length) return bad('Variable(s) desconocida(s): ' + unk.join(','));
const t0 = Date.now() - win * 60000;
const sel = S.history.filter(h => Date.parse(h.ts) >= t0);
const stride = Math.max(1, Math.ceil(sel.length / maxp));
const samples = [];
for (let i = 0; i < sel.length; i += stride) {
    const h = sel[i], o = { ts: h.ts, t_sim_s: h.t };
    for (const v of vars) o[v] = h[v];
    samples.push(o);
}
const units = {}; vars.forEach(v => units[v] = VARS[v]);
msg.statusCode = 200;
msg.payload = { device: 'B09', ts: new Date().toISOString(), window_min: win, vars, units, count: samples.length, samples };
return msg;

// GET /api/B09/alarms → alarmas vigentes + registro (últimos 100 eventos)
const S = global.get('b09');
if (!S) { msg.statusCode = 503; msg.payload = { error: 'Simulador no inicializado' }; return msg; }
msg.statusCode = 200;
msg.payload = { device: 'B09', ts: new Date().toISOString(),
    alarmas: Object.values(S.alarms), registro: S.alarm_log.slice(-100).reverse() };
return msg;

// GET /api/B09/alarms/:id → detalle de una alarma (404 si no existe)
const S = global.get('b09');
const id = String(msg.req.params.id || '').toUpperCase();
const KNOWN = ['ALM_PH', 'ALM_TURB', 'ALM_OVF', 'ALM_BOMBA'];
if (!KNOWN.includes(id)) {
    msg.statusCode = 404;
    msg.payload = { device: 'B09', ts: new Date().toISOString(), error: `Alarma '${id}' no existe`, alarmas_definidas: KNOWN };
    return msg;
}
msg.statusCode = 200;
msg.payload = { device: 'B09', ts: new Date().toISOString(), id,
    vigente: S.alarms[id] || null, registro: S.alarm_log.filter(e => e.id === id).slice(-50).reverse() };
return msg;

// GET /api/B09/commands/log → registro de solicitudes de control (código y tiempo)
const S = global.get('b09');
msg.statusCode = 200;
msg.payload = { device: 'B09', ts: new Date().toISOString(), registro: (S ? S.cmd_log : []).slice().reverse() };
return msg;

// ===== POST /api/B09/commands =====
// Cuerpo JSON: { "command": "<nombre>", ...parámetros }
// 200 ejecutado · 400 solicitud inválida/fuera de rango · 404 recurso inexistente · 409 incompatible con el estado
msg._t0 = Date.now(); msg._logCmd = true;
let S = global.get('b09');
const COMANDOS = ['bomba_on', 'bomba_off', 'dosificacion', 'descarga_on', 'descarga_off', 'falla_bomba',
                  'reparar_bomba', 'perturbacion', 'ack_alarma', 'ack_todas', 'reiniciar'];
function out(code, body) {
    msg.statusCode = code;
    msg.payload = Object.assign({ device: 'B09', ts: new Date().toISOString(), ok: code < 300, command: msg._cmd || null }, body);
    return msg;
}
if (!S) return out(503, { error: 'Simulador no inicializado' });
let b = msg.payload;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return out(400, { error: 'JSON inválido' }); } }
if (!b || typeof b !== 'object' || Array.isArray(b)) return out(400, { error: 'El cuerpo debe ser un objeto JSON', comandos_validos: COMANDOS });
const cmd = b.command; msg._cmd = typeof cmd === 'string' ? cmd : null;
if (typeof cmd !== 'string') return out(400, { error: "Falta el campo 'command'", comandos_validos: COMANDOS });

const c = S.cfg, p = S.proc, a = S.act, sp = S.sp;
const num = v => (typeof v === 'number' ? v : (typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN));
function ev(texto) { S.alarm_log.push({ ts: new Date().toISOString(), t_sim_s: Math.round(p.t_sim), tipo: 'COMANDO', id: cmd, texto, severidad: null });
    if (S.alarm_log.length > 500) S.alarm_log.shift(); }

switch (cmd) {
case 'bomba_on':
    if (a.bomba_falla) return out(409, { error: 'P-101 en falla: ejecute reparar_bomba antes de arrancar' });
    if (a.bomba_on) return out(409, { error: 'P-101 ya está en marcha' });
    if (sp.modo === 'auto' && p.V >= sp.nivel_alto_L) return out(409, { error: `Enclavamiento: nivel ${p.V.toFixed(0)} L ≥ nivel alto ${sp.nivel_alto_L} L` });
    a.bomba_on = true; a.motivo_bomba = 'comando remoto'; ev('P-101 arrancada');
    return out(200, { resultado: 'Bomba P-101 en marcha' });

case 'bomba_off':
    if (!a.bomba_on) return out(409, { error: 'P-101 ya está detenida' });
    a.bomba_on = false; a.motivo_bomba = 'comando remoto'; ev('P-101 detenida');
    return out(200, { resultado: 'Bomba P-101 detenida' });

case 'dosificacion': {
    const v = num(b.value);
    if (!Number.isFinite(v)) return out(400, { error: "Falta 'value' numérico (L/h)" });
    if (v < 0 || v > c.DOSE_MAX) return out(400, { error: `Dosificación fuera de rango: ${v} L/h (permitido 0–${c.DOSE_MAX})` });
    if (v > 0 && p.V <= 50) return out(409, { error: 'No se puede dosificar con el tanque vacío' });
    const prev = sp.dosificacion_Lh; sp.dosificacion_Lh = v; ev(`Dosificación ${prev} → ${v} L/h`);
    return out(200, { resultado: `Dosificación ajustada a ${v} L/h`, anterior: prev });
}

case 'descarga_on':
    if (a.descarga_on) return out(409, { error: 'La descarga ya está activa' });
    if (p.V < c.V_MIN_DESC) return out(409, { error: `Nivel insuficiente para descargar (${p.V.toFixed(0)} L < ${c.V_MIN_DESC} L)` });
    if (sp.modo === 'auto' && !p.en_spec) return out(409, { error: 'Agua fuera de especificación: en modo auto no se permite descargar',
        ph: +p.pH.toFixed(2), turbidez: +p.turb.toFixed(2) });
    a.descarga_on = true; ev('Descarga P-103 iniciada');
    return out(200, { resultado: 'Descarga iniciada', advertencia: p.en_spec ? undefined : 'Descargando agua fuera de especificación (modo manual)' });

case 'descarga_off':
    if (!a.descarga_on) return out(409, { error: 'La descarga no está activa' });
    a.descarga_on = false; ev('Descarga P-103 detenida');
    return out(200, { resultado: 'Descarga detenida' });

case 'falla_bomba':
    if (a.bomba_falla) return out(409, { error: 'P-101 ya está en falla' });
    a.bomba_falla = true; a.bomba_on = false; a.motivo_bomba = 'falla (disparo térmico simulado)'; ev('Falla inyectada en P-101');
    return out(200, { resultado: 'Falla inyectada en P-101' });

case 'reparar_bomba':
    if (!a.bomba_falla) return out(409, { error: 'P-101 no tiene falla activa' });
    a.bomba_falla = false; a.motivo_bomba = 'reparada, detenida'; ev('P-101 reparada');
    return out(200, { resultado: 'P-101 reparada (detenida; envíe bomba_on para arrancar)' });

case 'perturbacion': {
    const t = b.turbidez_entrada === undefined ? undefined : num(b.turbidez_entrada);
    const ph = b.ph_entrada === undefined ? undefined : num(b.ph_entrada);
    if (t === undefined && ph === undefined) return out(400, { error: "Indique 'turbidez_entrada' (1–500 NTU) y/o 'ph_entrada' (4–10)" });
    if (t !== undefined && (!Number.isFinite(t) || t < 1 || t > 500)) return out(400, { error: 'turbidez_entrada fuera de rango (1–500 NTU)' });
    if (ph !== undefined && (!Number.isFinite(ph) || ph < 4 || ph > 10)) return out(400, { error: 'ph_entrada fuera de rango (4–10)' });
    if (t !== undefined) { p.turb_in_base = t; p.turb_in = t; }
    if (ph !== undefined) p.pH_in = ph;
    ev(`Perturbación agua cruda: turbidez=${p.turb_in_base} NTU, pH=${p.pH_in}`);
    return out(200, { resultado: 'Perturbación aplicada', turbidez_entrada: p.turb_in_base, ph_entrada: p.pH_in });
}

case 'ack_alarma': {
    const id = typeof b.alarm_id === 'string' ? b.alarm_id.toUpperCase() : null;
    if (!id) return out(400, { error: "Falta 'alarm_id'" });
    if (!['ALM_PH', 'ALM_TURB', 'ALM_OVF', 'ALM_BOMBA'].includes(id)) return out(404, { error: `Alarma '${id}' no existe` });
    const A = S.alarms[id];
    if (!A) return out(409, { error: `La alarma ${id} no está pendiente` });
    if (A.reconocida) return out(409, { error: `La alarma ${id} ya fue reconocida` });
    A.reconocida = true; A.t_reconocimiento = new Date().toISOString();
    S.alarm_log.push({ ts: A.t_reconocimiento, t_sim_s: Math.round(p.t_sim), tipo: 'RECONOCIDA', id, texto: A.nombre, severidad: A.severidad });
    return out(200, { resultado: `Alarma ${id} reconocida`, alarma: A });
}

case 'ack_todas': {
    const pend = Object.values(S.alarms).filter(x => !x.reconocida);
    if (!pend.length) return out(409, { error: 'No hay alarmas pendientes de reconocimiento' });
    const t = new Date().toISOString();
    pend.forEach(A => { A.reconocida = true; A.t_reconocimiento = t;
        S.alarm_log.push({ ts: t, t_sim_s: Math.round(p.t_sim), tipo: 'RECONOCIDA', id: A.id, texto: A.nombre, severidad: A.severidad }); });
    return out(200, { resultado: `${pend.length} alarma(s) reconocida(s)`, ids: pend.map(x => x.id) });
}

case 'reiniciar': {
    const N = JSON.parse(global.get('b09_defaults'));
    N.meta = { iniciado: new Date().toISOString(), origen: 'reinicio' };
    N.cmd_log = S.cmd_log;            // se conserva el registro de comandos
    global.set('b09', N);
    return out(200, { resultado: 'Simulación reiniciada a condiciones iniciales' });
}

default:
    return out(400, { error: `Comando desconocido '${cmd}'`, comandos_validos: COMANDOS });
}

// ===== PUT /api/B09/setpoint =====
// Cuerpo JSON con uno o más campos. Se validan todos antes de aplicar (operación atómica).
msg._t0 = Date.now(); msg._logCmd = true; msg._cmd = 'setpoint';
const S = global.get('b09');
function out(code, body) {
    msg.statusCode = code;
    msg.payload = Object.assign({ device: 'B09', ts: new Date().toISOString(), ok: code < 300 }, body);
    return msg;
}
if (!S) return out(503, { error: 'Simulador no inicializado' });
const RULES = {
    dosificacion_Lh: { min: 0, max: S.cfg.DOSE_MAX, unit: 'L/h' },
    nivel_alto_L:    { min: 500, max: S.cfg.CAP, unit: 'L' },
    factor_tiempo:   { min: 1, max: 60, unit: 'x', int: true },
    latencia_ms:     { min: 0, max: 10000, unit: 'ms', int: true },
    modo:            { enum: ['auto', 'manual'] }
};
let b = msg.payload;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return out(400, { error: 'JSON inválido' }); } }
if (!b || typeof b !== 'object' || Array.isArray(b) || !Object.keys(b).length)
    return out(400, { error: 'Envíe un objeto JSON con al menos un campo', campos: RULES });
const errores = [], cambios = {};
for (const [key, val] of Object.entries(b)) {
    const R = RULES[key];
    if (!R) { errores.push(`Campo desconocido '${key}'`); continue; }
    if (R.enum) { if (!R.enum.includes(val)) errores.push(`${key} debe ser uno de: ${R.enum.join(', ')}`); else cambios[key] = val; continue; }
    const v = typeof val === 'number' ? val : Number(val);
    if (val === null || val === '' || !Number.isFinite(v)) { errores.push(`${key} debe ser numérico`); continue; }
    if (R.int && !Number.isInteger(v)) { errores.push(`${key} debe ser entero`); continue; }
    if (v < R.min || v > R.max) { errores.push(`${key}=${v} fuera de rango (${R.min}–${R.max} ${R.unit})`); continue; }
    cambios[key] = v;
}
if (errores.length) return out(400, { error: errores.join('; '), errores, campos: RULES });
if (cambios.dosificacion_Lh > 0 && S.proc.V <= 50) return out(409, { error: 'No se puede dosificar con el tanque vacío' });
const anterior = {};
for (const k of Object.keys(cambios)) anterior[k] = S.sp[k];
Object.assign(S.sp, cambios);
S.alarm_log.push({ ts: new Date().toISOString(), t_sim_s: Math.round(S.proc.t_sim), tipo: 'CONSIGNA', id: 'setpoint',
    texto: Object.entries(cambios).map(([k, v]) => `${k}: ${anterior[k]} → ${v}`).join(', '), severidad: null });
return out(200, { resultado: 'Consignas actualizadas', aplicados: cambios, anterior, setpoints: S.sp });

// ===== B09 · Restaurar / crear estado =====
// Entrada: msg.payload = objeto leído de b09_persist.json (o nada si el archivo no existe).
// Crea el estado inicial y, si hay archivo válido, recupera el estado persistido.
function defaults() {
    return {
        device: 'B09',
        version: 1,
        // Constantes físicas del modelo (no se persisten: siempre se toman del código)
        cfg: {
            CAP: 3000,          // capacidad del tanque [L]
            QIN_NOM: 60,        // caudal nominal bomba de alimentación P-101 [L/min]
            QOUT_NOM: 90,       // caudal nominal bomba de descarga P-103 [L/min]
            DOSE_MAX: 10,       // dosificación máxima de coagulante [L/h]
            TAU_DOSE: 120,      // retardo (1er orden) de la dosificación [s]
            TAU_PH: 180,        // constante de tiempo del pH [s]
            ALPHA: 0.25,        // descenso de pH por cada L/h de coagulante efectivo [pH/(L/h)]
            KMAX: 0.012,        // tasa máxima de remoción de turbidez [1/s]
            KD: 1.5,            // dosis de semi-saturación [L/h]
            PH_MIN: 6.5, PH_MAX: 8.5,
            TURB_OBJ: 5,        // turbidez objetivo [NTU]
            V_MIN_DESC: 100,    // volumen mínimo para iniciar descarga [L]
            HIST_MAX: 3600      // muestras de histórico (1 por segundo real = 60 min)
        },
        // Consignas (modificables por PUT /setpoint)
        sp: { modo: 'auto', nivel_alto_L: 2800, dosificacion_Lh: 2.0, factor_tiempo: 10, latencia_ms: 0 },
        // Estado del proceso
        proc: { t_sim: 0, V: 1200, pH: 7.3, turb: 3.0, Qin: 0, Qout: 0, dose_eff: 2.0,
                overflow: false, en_spec: true, pH_in: 7.8, turb_in: 40, turb_in_base: 40 },
        // Actuadores
        act: { bomba_on: false, bomba_falla: false, descarga_on: false, motivo_bomba: 'inicio' },
        // Acumuladores de KPI (tiempos en s simulados, volúmenes en L)
        kpi: { t_total: 0, t_spec: 0, t_disp: 0, reactivo_L: 0, tratado_L: 0, descargado_L: 0, rebose_L: 0 },
        alarms: {}, alarm_log: [], history: [], cmd_log: []
    };
}

// Plantilla para el comando "reiniciar" (lo usa el flujo de Comunicaciones)
global.set('b09_defaults', JSON.stringify(defaults()));

let S = defaults();
let origen = 'inicial';
const saved = msg.payload;
if (saved && typeof saved === 'object' && saved.device === 'B09' && saved.version === 1) {
    for (const k of ['sp', 'proc', 'act', 'kpi']) Object.assign(S[k], saved[k] || {});
    for (const k of ['alarms', 'alarm_log', 'history', 'cmd_log']) if (saved[k]) S[k] = saved[k];
    origen = 'archivo';
}
S.meta = { iniciado: new Date().toISOString(), origen };
global.set('b09', S);
node.status({ fill: 'green', shape: 'dot', text: 'estado ' + origen });
return { payload: S.meta };

const S = global.get('b09');
if (!S) return null;
msg.payload = JSON.stringify(S);
node.status({text: 'guardado ' + new Date().toLocaleTimeString()});
return msg;
